/* ==========================================================================
   TENGEN PIXEL — Entertainment District pixel-art Obsidian theme
   Same technique as the DND vault's dnd-pixel theme: a pixel-art SVG scene behind
   translucent panes, Pixelify Sans headings, hard 3px borders, offset block shadows.
   GENERATED: edit src/*.css, src/pixel-scene.js or categories.json, then `node tools/vault.js build`.
   ========================================================================== */
@import url('https://fonts.googleapis.com/css2?family=Pixelify+Sans:wght@500;700&family=Nunito:wght@400;600;800&display=swap');

html { background: #04021a !important; }
body.theme-dark, body.theme-light {
  --font-text-theme: 'Nunito'; --font-interface-theme: 'Nunito';
  --background-primary: #0a0630; --background-primary-alt: #110a46; --background-secondary: #070424; --background-secondary-alt: #0d0838;
  --background-modifier-border: #3d2fae; --background-modifier-border-hover: #7a6aff; --background-modifier-hover: rgba(255, 179, 71, 0.10);
  --background-modifier-form-field: #0a0636; --background-modifier-cover: rgba(10, 5, 24, 0.85);
  --text-normal: #f6eeff; --text-muted: #c0aee6; --text-faint: #8470b0;
  --text-accent: #ffb347; --text-accent-hover: #ffd28a; --interactive-accent: #8a2be2; --interactive-accent-hover: #ff4fa0; --text-on-accent: #ffffff;
  --interactive-normal: #1a1066; --interactive-hover: #2a1a99;
  --link-color: #ff8ad8; --link-color-hover: #ffe9a8; --link-unresolved-color: #9a86c9; --tag-color: #9bf6ff; --tag-background: rgba(155, 246, 255, 0.10);
  --h1-color: #ffb347; --h2-color: #ff4fa0; --h3-color: #ff8ad8; --h4-color: #b78bff; --h5-color: #5ea0ff; --h6-color: #6ff3ff;
  --bold-color: #ffe9a8; --italic-color: #ffd2f5;
  --table-border-color: #3d2fae; --table-header-background: rgba(255, 179, 71, 0.10); --blockquote-border-color: #ff4fa0;
  --code-background: #130a2b; --code-normal: #9bf6ff; --hr-color: #3d2fae;
  --text-selection: rgba(255, 79, 160, 0.4);
  --graph-line: rgba(200, 170, 255, 0.22); --graph-node: #b78bff; --graph-node-unresolved: #3d2fae; --graph-node-focused: #ffb347; --graph-node-tag: #ffb347;
  --scrollbar-bg: transparent; --scrollbar-thumb-bg: #3d2fae; --scrollbar-active-thumb-bg: #ff4fa0;
  --tg-a1: #ffb347; --tg-a1-rgb: 255, 179, 71; --tg-a2: #ff4fa0; --tg-a2-rgb: 255, 79, 160;
  --tg-bd: #3d2fae; --tg-bd-rgb: 61, 47, 174; --tg-bd2: #7a6aff; --tg-btn: #8a2be2;
  --tg-bg-rgb: 8, 5, 38; --tg-bg2-rgb: 6, 3, 28; --tg-ink-rgb: 4, 2, 22;
  --tg-pane: rgba(var(--tg-bg-rgb), 0.78); --tg-side: rgba(var(--tg-bg2-rgb), 0.84); --tg-graph: rgba(var(--tg-ink-rgb), 0.30);
  --tg-pixel: 'Pixelify Sans', var(--font-interface-theme), monospace;
  --font-ui-smaller: 13px; --font-ui-small: 14px; --font-ui-medium: 16px; --font-ui-large: 21px;
  --radius-s: 0px; --radius-m: 0px; --radius-l: 0px; --checkbox-radius: 0px;
}


/* ==========================================================================
   CHROME — scene behind everything, translucent panes, pixel controls
   ========================================================================== */
body { background: transparent !important; }
body::before { content: ""; position: fixed; inset: 0; z-index: -1; pointer-events: none; image-rendering: pixelated; background: #04021a url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-giyu::before { background: #020a1c url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-shinobu::before { background: #0c0418 url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-rengoku::before { background: #160302 url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-muichiro::before { background: #060f16 url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-mitsuri::before { background: #14030e url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-obanai::before { background: #020c08 url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-gyomei::before { background: #0e0805 url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
body.tg-char-sanemi::before { background: #030e0a url("data:image/svg+xml;base64,") right bottom / cover no-repeat; }
.app-container, .horizontal-main-container, .workspace, .workspace-split, .workspace-tabs, .workspace-tab-container, .workspace-leaf, .workspace-tab-header-container,
.workspace-tab-header-container-inner, .workspace-ribbon, .side-dock-ribbon, .titlebar, .titlebar-inner, .status-bar, .workspace-sidedock-vault-profile { background: transparent !important; }
.workspace-leaf-content { background-color: var(--tg-pane) !important; }
.mod-left-split .workspace-leaf-content, .mod-right-split .workspace-leaf-content { background-color: var(--tg-side) !important; }
.workspace-leaf-content .view-header, .view-content, .markdown-reading-view, .markdown-preview-view, .markdown-source-view, .cm-editor, .cm-scroller, .cm-gutters, .nav-files-container { background-color: transparent !important; }
.workspace-leaf-content[data-type="graph"], .workspace-leaf-content[data-type="localgraph"] { background-color: var(--tg-graph) !important; }
.workspace-leaf-content[data-type="graph"] canvas, .workspace-leaf-content[data-type="localgraph"] canvas { background: transparent !important; filter: drop-shadow(0 0 2px rgba(0, 0, 0, 0.9)); }
/* "no file open": the scene at full brightness */
.workspace-leaf-content[data-type="empty"] { background-color: transparent !important; }
.empty-state-title { font-family: var(--tg-pixel); font-size: 2em; color: var(--tg-a1); text-shadow: 3px 3px 0 #1a1426; }
.empty-state-action { font-family: var(--tg-pixel); color: var(--link-color); text-shadow: 2px 2px 0 #1a1426; }

/* pixel UI: no rounding, hard borders, block shadows */
*, *::before, *::after { border-radius: 0 !important; }
.status-bar { background: rgba(var(--tg-ink-rgb), 0.9) !important; border-top: 3px solid var(--tg-bd); }
.workspace-tab-header.is-active { box-shadow: inset 0 -3px 0 var(--tg-a1); }
.workspace-tab-header.is-active .workspace-tab-header-inner-title { font-family: var(--tg-pixel); color: var(--tg-a1); }
.workspace-tab-header-inner-title, .nav-file-title-content, .nav-folder-title-content { font-family: var(--tg-pixel); letter-spacing: 0.02em; }
.nav-folder-title { font-weight: 700; }
.nav-file-title.is-active, .nav-folder-title.is-active { box-shadow: inset 4px 0 0 var(--tg-a1); background: rgba(var(--tg-a1-rgb), 0.12); }
button, .clickable-icon { transition: none; }
button { border: 3px solid var(--tg-bd); box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.5); font-family: var(--tg-pixel); }
button:hover { border-color: var(--tg-a1); }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 rgba(0, 0, 0, 0.5); }
button.mod-cta { background: var(--tg-btn); border-color: #1a1426; color: #fff; }
button.mod-cta:hover { background: var(--tg-a2); }
input[type="text"], input[type="search"], input[type="number"], textarea, select, .dropdown { border: 3px solid var(--tg-bd); background: var(--background-modifier-form-field); }
input:focus, textarea:focus { border-color: var(--tg-a1); box-shadow: none; }
input[type="checkbox"] { border: 2px solid var(--tg-a1); }
input[type="checkbox"]:checked { background-color: var(--tg-btn); }
::-webkit-scrollbar { width: 12px; height: 12px; }
::-webkit-scrollbar-thumb { background: var(--tg-bd); border: 2px solid var(--background-modifier-form-field); }
::-webkit-scrollbar-thumb:hover { background: var(--tg-a2); }

/* modals, menus, popovers: solid, bordered like RPG dialogue boxes */
.modal, .menu, .suggestion-container, .popover, .prompt, .notice, .tooltip { background-color: var(--background-primary) !important; border: 3px solid var(--tg-a1) !important; box-shadow: 5px 5px 0 rgba(0, 0, 0, 0.6) !important; }
.popover .workspace-leaf-content, .popover .view-content, .modal .workspace-leaf-content { background-color: var(--background-primary) !important; }
.suggestion-item.is-selected, .menu-item:hover { background: rgba(var(--tg-a2-rgb), 0.3); }
.graph-controls { background-color: rgba(var(--tg-bg-rgb), 0.94) !important; border: 3px solid var(--tg-a1) !important; }

/* ---------------- mobile (Obsidian phone/tablet app adds body.is-mobile) ---------------- */
body.is-mobile { --tg-pane: rgba(var(--tg-bg-rgb), 0.84); --tg-side: rgba(var(--tg-bg2-rgb), 0.94); }
body.is-mobile .workspace-drawer, body.is-mobile .workspace-drawer-inner, body.is-mobile .workspace-drawer .workspace-leaf-content { background-color: rgba(var(--tg-bg2-rgb), 0.96) !important; border-color: var(--tg-bd); }
body.is-mobile .mobile-navbar { background-color: rgba(var(--tg-ink-rgb), 0.97) !important; border-top: 3px solid var(--tg-bd); }
body.is-mobile .mobile-navbar-action, body.is-mobile .mobile-navbar-action svg { color: var(--tg-a1); }
body.is-mobile .view-header-title { font-family: var(--tg-pixel); }
body.is-mobile .inline-title { font-size: 1.8em; }
body.is-mobile .markdown-rendered h1 { font-size: 1.6em; }
body.is-mobile .callout { box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.5); }
body.is-mobile .markdown-rendered table { display: block; overflow-x: auto; }
body.is-mobile button, body.is-mobile .clickable-icon { min-height: 40px; }

/* pixel character portraits embedded in notes (chibi-*.svg) */
.markdown-rendered img[src*="chibi"], .markdown-source-view img[src*="chibi"] { image-rendering: pixelated; display: block; margin: 0.4em auto; filter: drop-shadow(3px 3px 0 rgba(0, 0, 0, 0.55)); }


/* ==========================================================================
   TYPOGRAPHY — pixel headings, RPG dialogue-box callouts, block-shadow tables
   ========================================================================== */
.markdown-rendered, .markdown-source-view.mod-cm6 { line-height: 1.7; }
.markdown-rendered h1, .markdown-rendered h2, .markdown-rendered h3, .markdown-rendered h4, .inline-title, .cm-header-1, .cm-header-2, .cm-header-3 { font-family: var(--tg-pixel); letter-spacing: 0.03em; }
.markdown-rendered h1, .inline-title { text-shadow: 3px 3px 0 var(--tg-bd); }
.inline-title { font-size: 2.4em; color: var(--tg-a1); }
.markdown-rendered h1 { border-bottom: 4px solid var(--tg-a2); padding-bottom: 4px; }
.markdown-rendered h2 { border-bottom: 3px dashed var(--tg-bd); padding-bottom: .15em; text-shadow: 2px 2px 0 #1a1426; }
.markdown-rendered h2::before { content: "\25A0  "; color: var(--tg-a2); font-size: .6em; vertical-align: middle; }
.markdown-rendered img, .markdown-rendered img[src$=".svg"] { image-rendering: pixelated; }

a, .cm-hmd-internal-link, .internal-link { text-decoration: none; }
.markdown-rendered a.internal-link, .cm-hmd-internal-link .cm-underline { border-bottom: 2px solid currentColor; text-decoration: none; }
.markdown-rendered a.internal-link:hover { background: rgba(var(--tg-a1-rgb), 0.18); color: var(--tg-a1); }
.internal-link.is-unresolved { border-bottom-style: dotted !important; opacity: .75; }

blockquote, .markdown-rendered blockquote { border-left: 5px solid var(--tg-a2); background: rgba(var(--tg-a2-rgb), 0.08); padding: .4em 1em; }
.callout { border: 3px solid rgba(var(--callout-color), 0.9) !important; box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.5); background: rgba(var(--tg-ink-rgb), 0.55); }
.callout-title { font-family: var(--tg-pixel); font-weight: 700; letter-spacing: .03em; }
.markdown-rendered table { border: 3px solid var(--tg-bd); box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4); background: rgba(var(--tg-ink-rgb), 0.45); }
.markdown-rendered thead th { background: var(--tg-bd); color: var(--tg-a1); font-family: var(--tg-pixel); }
.markdown-rendered pre { border: 3px solid var(--tg-bd); box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4); }
.markdown-rendered code { color: #9bf6ff; }
.markdown-rendered ul > li::marker { color: var(--tg-a2); }
.markdown-rendered ol > li::marker { color: var(--tg-a1); font-family: var(--tg-pixel); }
.markdown-rendered hr { border: 0; height: 4px; background: repeating-linear-gradient(90deg, var(--tg-a2) 0 8px, transparent 8px 12px); }
a.tag, .cm-hashtag { padding: 0 .55em; border: 2px solid currentColor; font-family: var(--tg-pixel); font-weight: 600; }
.metadata-container { border: 3px solid var(--tg-bd); padding: .4em .8em; background: rgba(var(--tg-ink-rgb), 0.5); box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.35); }
.metadata-property-key { font-family: var(--tg-pixel); color: var(--text-muted); }
.tree-item-flair { background: var(--tg-btn); color: #fff; font-family: var(--tg-pixel); }


/* ==========================================================================
   CATEGORIES  —  generated from categories.json (colour-sorted system)
   folder tree · note page accents · tags · callouts · graph palette vars
   Applied to a note via frontmatter:  cssclasses: [cat-<id>]
   ========================================================================== */
